msg.payload = {
    device_id: "Compressor1",
    device_name: "Compressor System",

    compressor_temperature: compressor,
    blower_temperature: blower,
    environment_temperature: environment,

    status: 1,
    time: timestamp
};

// Clear values after successful send to prevent stale data
flow.set("compressor", undefined);
flow.set("blower", undefined);
flow.set("environment", undefined);

return msg;

// 1. Set the Header (So Flask knows it's JSON)
msg.headers = { 'Content-Type': 'application/json' };

// 2. Get the Temperature value
// (Assuming your Modbus Read outputs an array, and the value is at index 1)
// If your Modbus node output is just [245], change index to [0]
var raw_value = msg.payload[0]; 
var temperature = raw_value / 10.0;

// 3. Create the JSON Object (The critical fix)
// We UPDATE msg.payload, we do NOT replace 'msg'
msg.payload = {
    "temperature": temperature
};

return msg;

// Extract all 4 values from Python
var health = msg.payload.health;
var critical_incidents = msg.payload.critical_events; 
var raw_anomalies = msg.payload.total_anomalies; // <--- The new raw count
// --- OUTPUT 1: Status ---
var color = "green";
if (health === "WARNING") color = "#ffbf00"; // Yellow
if (health === "CRITICAL") color = "red";    // Red
var msg1 = { payload: health, color: color };

// --- OUTPUT 2: Total Anomalies ---
var msg2 = { payload: raw_anomalies };

// --- OUTPUT 3: Critical Incidents ---
var msg3 = { payload: critical_incidents };

return [msg1, msg2, msg3];

// Output 1: Actual Temperature (Always exists)
var msg1 = { payload: msg.payload.temperature };

// Output 2: Forecast (Only exists after buffering is done)
var msg2 = null;

// Check if forecast exists before trying to send it
if (msg.payload.forecast !== undefined) {
    msg2 = { payload: msg.payload.forecast };
}

// If msg2 is null, Node-RED sends nothing on the second wire
return [msg1, msg2];

// Check if the system is still buffering (warming up)
if (msg.payload.status === "buffering") {
    msg.payload = "⏳ WARMING UP...";
    msg.color = "#ffbf00"; // Amber color for waiting
}
// Check if the forecast exists (Success state)
else if (msg.payload.forecast !== undefined) {
    msg.payload = msg.payload.forecast + " °C";
    msg.color = "#00bcd4"; // Cyan/Blue color for normal
}
// Fallback for errors
else {
    msg.payload = "--.-";
    msg.color = "gray";
}

return msg;

var current = msg.payload.temperature;

// 1. Get the current date as a string (e.g., "2023-10-27")
var now = new Date();
var todayDate = now.toISOString().split('T')[0];

// 2. Retrieve the last saved date
var lastDate = flow.get('last_process_date');

// 3. Initialize variables
var max, min;

// CHECK: Is it a new day? OR is this the first time running?
if (todayDate !== lastDate) {
    // It is a new day! Reset max and min to the CURRENT temperature
    max = current;
    min = current;

    // Save the new date so we know we've handled today
    flow.set('last_process_date', todayDate);
} else {
    // It is the same day. Retrieve existing values.
    max = flow.get('daily_max');
    min = flow.get('daily_min');

    // Safety check: if memory was wiped manually, treat as current
    if (max === undefined) max = current;
    if (min === undefined) min = current;

    // Standard comparison logic
    if (current > max) max = current;
    if (current < min) min = current;
}

// 4. Save the values back to memory
flow.set('daily_max', max);
flow.set('daily_min', min);

// 5. Output
msg.payload = { 
    max: max, 
    min: min, 
    date: todayDate 
};

return msg;

var now = new Date();
// Format: HH:MM:SS
var timeString = now.toLocaleTimeString();
msg.payload = "Last Sync: " + timeString;
return msg;

// Retrieve the 4 values we just memorized above!
let rate = flow.get("fm_rate") || 0;
let velocity = flow.get("fm_velocity") || 0;
let voltage = flow.get("fm_voltage") || 0;
let upper = flow.get("fm_upper") || 0;

// The Lower Limit is the current message payload
let lower = msg.payload;

// Format the SQL Query to send all 5 values at once
msg.topic = `INSERT INTO FlowMeter_Data (flow_rate, flow_velocity, sensor_voltage, upper_limit, lower_limit) 
             VALUES (${rate}, ${velocity}, ${voltage}, ${upper}, ${lower})`;

return msg;

// Retrieve the previously saved values from the flow
let avg_v = flow.get("pm_avg_v") || 0;
let avg_c = flow.get("pm_avg_c") || 0;
let total_p = flow.get("pm_total_p") || 0;
let line_v = flow.get("pm_line_v") || 0;
let pf = flow.get("pm_pf") || 0;

// The Frequency is the current message payload
let freq = msg.payload;

// Format the SQL Query
msg.topic = `INSERT INTO PowerMeter_Data (average_voltage, average_current, total_power, average_line_voltage, power_factor, frequency) 
             VALUES (${avg_v}, ${avg_c}, ${total_p}, ${line_v}, ${pf}, ${freq})`;

return msg;

let today=new Date();
if(today.getDate()===1)return msg;
return null;

if(!msg.payload || !msg.payload.freqs) return null;

var freqs = msg.payload.freqs;
var mags = msg.payload.magnitudes;
flow.set('fft_peaks', msg.payload.peaks || []);

var yValues = [];
var xLabels = [];
var myColors = []; // Array to hold our custom colors

for(var i = 0; i < freqs.length; i++){
    if(freqs[i] > 5.0) break;

    var hz = freqs[i].toFixed(2) + ' Hz';
    var mag = parseFloat(mags[i].toFixed(5));

    xLabels.push(hz);
    yValues.push(mag);

    // 🚀 THE UPGRADE: Dynamic Severity Colors based on height
    if (mag > 0.0015) {
        myColors.push('#e2534a'); // Red (Danger / High Peak)
    } else if (mag > 0.0008) {
        myColors.push('#ef9f27'); // Orange (Warning / Medium Peak)
    } else {
        myColors.push('#3b8bd4'); // Blue (Normal / Safe)
    }
}

msg.payload = [{
    "series": ["Magnitude"],
    "data": [yValues],
    "labels": xLabels
}];

// Override the dashboard's default 9-color limit with our custom array
msg.colors = myColors;

return msg;

var peaks = flow.get('fft_peaks') || [];
if (peaks.length === 0) { msg.payload = { status: 'ok', peaks: [] }; return msg; }

function classify(hint, freq) {
    hint = (hint || '').toLowerCase();
    if (freq < 0.1)   return { label: 'Sensor drift',     icon: '~', color: '#888',    tip: 'Normal — ignore' };
    if (hint.indexOf('bearing')   >= 0) return { label: 'Bearing wear',    icon: '!', color: '#e2534a', tip: 'Inspect soon' };
    if (hint.indexOf('imbalance') >= 0) return { label: 'Imbalance',       icon: '!', color: '#e2534a', tip: 'Schedule check' };
    if (hint.indexOf('looseness') >= 0) return { label: 'Looseness',       icon: '!', color: '#ef9f27', tip: 'Check bolts' };
    if (hint.indexOf('resonance') >= 0) return { label: 'Frame resonance', icon: '·', color: '#5daa85', tip: 'Monitor only' };
    return                               { label: 'Unknown',               icon: '?', color: '#888',    tip: 'Monitor' };
}

var maxMag = Math.max.apply(null, peaks.map(function(p){ return p.magnitude; }));

var mapped = peaks.map(function(p, i) {
    var c = classify(p.fault_hint, p.freq_hz);
    return {
        rank:    i + 1,
        freq:    p.freq_hz,
        pct:     Math.round((p.magnitude / maxMag) * 100),
        label:   c.label,
        tip:     c.tip,
        color:   c.color
    };
});

// Overall status
var urgent = mapped.filter(function(p){ return p.color === '#e2534a'; });
var status = urgent.length > 0 ? 'warn' : 'ok';

msg.payload = { status: status, peaks: mapped };
return msg;

if (!msg.payload || !msg.payload.history) return null;

var history = msg.payload.history;
var threshold = (msg.payload.envelope && msg.payload.envelope.threshold) ? msg.payload.envelope.threshold : null;

// Prevent crashing if the API history is temporarily empty
if (history.length === 0) return null;

var scoreSeries = history.map(function (h) {
    return {
        x: new Date(h.ts).getTime(),
        y: parseFloat(h.score.toFixed(4))
    };
});

// Setup the base chart data structure
var chartData = {
    "series": ["Anomaly Score"],
    "data": [scoreSeries],
    "labels": [""]
};

// If we have a threshold, add it as a second line on the same chart
if (threshold !== null) {
    var thresholdSeries = [
        { x: scoreSeries[0].x, y: threshold },
        { x: scoreSeries[scoreSeries.length - 1].x, y: threshold }
    ];
    chartData.series.push("AI Threshold");
    chartData.data.push(thresholdSeries);
}

msg.payload = [chartData];
return msg;

var env=msg.payload;
if(!env||!env.features){node.warn('Envelope not ready. Run train.py first.');return null;}
var vib=env.features['Total_Vib(g)'];
